// ─── Stack strip ─────────────────────────────────────────────────────
function StackStrip({ variant }: { variant: Variant }) {
  const icons = variant === "A" ? ENGINEERING_STACK : MARKETING_STACK;
  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={variant + "-stack"}
        initial={{ opacity: 0, y: 6 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -6 }}
        transition={{ duration: 0.2 }}
        className="flex flex-wrap items-center gap-3"
      >
        <span
          className="text-[10px] tracking-[0.18em] uppercase flex-shrink-0"
          style={{
            color: "rgba(255, 255, 255, 0.371)",
            fontFamily: "monospace",
          }}
        >
          {variant === "A" ? "Tech Stack" : "Marketing Stack"}
        </span>
        {icons.map(({ name, svg }) => (
          <div
            key={name}
            className="group relative opacity-45 hover:opacity-100 transition-opacity duration-200"
            title={name}
            style={{ width: 26, height: 26 }}
          >
            {svg}
            <span
              className="absolute -bottom-6 left-1/2 -translate-x-1/2 text-[9px] whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10"
              style={{
                color: "rgba(255,255,255,0.5)",
                fontFamily: "monospace",
              }}
            >
              {name}
            </span>
          </div>
        ))}
      </motion.div>
    </AnimatePresence>
  );
}

